<script>
// CHIP-8 Emulator
const FONTSET = [
  0xF0, 0x90, 0x90, 0x90, 0xF0, // 0
  0x20, 0x60, 0x20, 0x20, 0x70, // 1
  0xF0, 0x10, 0xF0, 0x80, 0xF0, // 2
  0xF0, 0x10, 0xF0, 0x10, 0xF0, // 3
  0x90, 0x90, 0xF0, 0x10, 0x10, // 4
  0xF0, 0x80, 0xF0, 0x10, 0xF0, // 5
  0xF0, 0x80, 0xF0, 0x90, 0xF0, // 6
  0xF0, 0x10, 0x20, 0x40, 0x40, // 7
  0xF0, 0x90, 0xF0, 0x90, 0xF0, // 8
  0xF0, 0x90, 0xF0, 0x10, 0xF0, // 9
  0xF0, 0x90, 0xF0, 0x90, 0x90, // A
  0xE0, 0x90, 0xE0, 0x90, 0xE0, // B
  0xF0, 0x80, 0x80, 0x80, 0xF0, // C
  0xE0, 0x90, 0x90, 0x90, 0xE0, // D
  0xF0, 0x80, 0xF0, 0x80, 0xF0, // E
  0xF0, 0x80, 0xF0, 0x80, 0x80  // F
];

const DISPLAY_WIDTH = 64;
const DISPLAY_HEIGHT = 32;
const MEMORY_SIZE = 4096;
const FONTSET_ADDRESS = 0x050;
const PROGRAM_ADDRESS = 0x200;

const KEY_MAPPING = {
  '1': 0x1, '2': 0x2, '3': 0x3, '4': 0xC,
  'q': 0x4, 'w': 0x5, 'e': 0x6, 'r': 0xD,
  'a': 0x7, 's': 0x8, 'd': 0x9, 'f': 0xE,
  'z': 0xA, 'x': 0x0, 'c': 0xB, 'v': 0xF
};

class Chip8 {
  constructor() {
    this.memory = new Uint8Array(MEMORY_SIZE);
    this.V = new Uint8Array(16);
    this.I = 0;
    this.pc = PROGRAM_ADDRESS;
    this.stack = [];
    this.sp = 0;
    this.delayTimer = 0;
    this.soundTimer = 0;
    this.display = new Uint8Array(DISPLAY_WIDTH * DISPLAY_HEIGHT);
    this.key = new Uint8Array(16);
    this.drawFlag = false;
    this.running = false;

    this.loadFontset();
  }

  loadFontset() {
    for (let i = 0; i < FONTSET.length; i++) {
      this.memory[FONTSET_ADDRESS + i] = FONTSET[i];
    }
  }

  loadROM(rom) {
    for (let i = 0; i < rom.length; i++) {
      this.memory[PROGRAM_ADDRESS + i] = rom[i];
    }
    this.pc = PROGRAM_ADDRESS;
    this.stack = [];
    this.sp = 0;
    this.V = new Uint8Array(16);
    this.I = 0;
    this.delayTimer = 0;
    this.soundTimer = 0;
    this.display = new Uint8Array(DISPLAY_WIDTH * DISPLAY_HEIGHT);
    this.drawFlag = false;
  }

  fetch() {
    return (this.memory[this.pc] << 8) | this.memory[this.pc + 1];
  }

  execute(opcode) {
    const X = (opcode & 0x0F00) >> 8;
    const Y = (opcode & 0x00F0) >> 4;
    const N = opcode & 0x000F;
    const NN = opcode & 0x00FF;
    const NNN = opcode & 0x0FFF;

    // Decode and display current instruction
    this.decodedInstruction = this.decodeInstruction(opcode);

    switch (opcode & 0xF000) {
      case 0x0000:
        switch (NNN) {
          case 0x00E0: // 00E0 - Clear display
            this.display = new Uint8Array(DISPLAY_WIDTH * DISPLAY_HEIGHT);
            this.drawFlag = true;
            break;
          case 0x00EE: // 00EE - Return from subroutine
            this.sp--;
            this.pc = this.stack[this.sp];
            break;
          default:
            console.log('Unknown opcode: ' + opcode.toString(16));
        }
        break;

      case 0x1000: // 1NNN - Jump to address NNN
        this.pc = NNN;
        break;

      case 0x2000: // 2NNN - Call subroutine at NNN
        this.stack[this.sp] = this.pc;
        this.sp++;
        this.pc = NNN;
        break;

      case 0x3000: // 3XNN - Skip if VX == NN
        if (this.V[X] === NN) {
          this.pc += 4;
        } else {
          this.pc += 2;
        }
        return;

      case 0x4000: // 4XNN - Skip if VX != NN
        if (this.V[X] !== NN) {
          this.pc += 4;
        } else {
          this.pc += 2;
        }
        return;

      case 0x5000: // 5XY0 - Skip if VX == VY
        if (this.V[X] === this.V[Y]) {
          this.pc += 4;
        } else {
          this.pc += 2;
        }
        return;

      case 0x6000: // 6XNN - Set VX = NN
        this.V[X] = NN;
        this.pc += 2;
        break;

      case 0x7000: // 7XNN - Add NN to VX
        this.V[X] = (this.V[X] + NN) & 0xFF;
        this.pc += 2;
        break;

      case 0x8000:
        switch (N) {
          case 0x0: // 8XY0 - Set VX = VY
            this.V[X] = this.V[Y];
            break;
          case 0x1: // 8XY1 - Set VX = VX | VY
            this.V[X] = this.V[X] | this.V[Y];
            break;
          case 0x2: // 8XY2 - Set VX = VX & VY
            this.V[X] = this.V[X] & this.V[Y];
            break;
          case 0x3: // 8XY3 - Set VX = VX ^ VY
            this.V[X] = this.V[X] ^ this.V[Y];
            break;
          case 0x4: // 8XY4 - Add VY to VX, set VF = carry
            const sum = this.V[X] + this.V[Y];
            this.V[0xF] = sum > 0xFF ? 1 : 0;
            this.V[X] = sum & 0xFF;
            break;
          case 0x5: // 8XY5 - Subtract VY from VX, set VF = NOT borrow
            this.V[0xF] = this.V[X] > this.V[Y] ? 1 : 0;
            this.V[X] = (this.V[X] - this.V[Y]) & 0xFF;
            break;
          case 0x6: // 8XY6 - Shift right VX, set VF = LSB
            this.V[0xF] = this.V[X] & 0x1;
            this.V[X] = this.V[X] >> 1;
            break;
          case 0x7: // 8XY7 - Subtract VX from VY, set VF = NOT borrow
            this.V[0xF] = this.V[Y] > this.V[X] ? 1 : 0;
            this.V[X] = (this.V[Y] - this.V[X]) & 0xFF;
            break;
          case 0x8: // 8XYE - Shift left VX, set VF = MSB
            this.V[0xF] = (this.V[X] & 0x80) >> 7;
            this.V[X] = (this.V[X] << 1) & 0xFF;
            break;
          default:
            console.log('Unknown opcode: ' + opcode.toString(16));
        }
        this.pc += 2;
        break;

      case 0x9000: // 9XY0 - Skip if VX != VY
        if (this.V[X] !== this.V[Y]) {
          this.pc += 4;
        } else {
          this.pc += 2;
        }
        return;

      case 0xA000: // ANNN - Set I = NNN
        this.I = NNN;
        this.pc += 2;
        break;

      case 0xB000: // BNNN - Jump to V0 + NNN
        this.pc = (this.V[0] + NNN) & 0xFFFF;
        break;

      case 0xC000: // CXNN - Set VX = random byte & NN
        this.V[X] = Math.floor(Math.random() * 256) & NN;
        this.pc += 2;
        break;

      case 0xD000: // DXYN - Draw sprite at I to (VX, VY)
        const x = this.V[X];
        const y = this.V[Y];
        const height = N;
        this.V[0xF] = 0;

        for (let row = 0; row < height; row++) {
          const spriteByte = this.memory[this.I + row];
          for (let col = 0; col < 8; col++) {
            if ((spriteByte & (0x80 >> col)) !== 0) {
              const pixelX = (x + col) % DISPLAY_WIDTH;
              const pixelY = (y + row) % DISPLAY_HEIGHT;
              const idx = pixelY * DISPLAY_WIDTH + pixelX;

              if (this.display[idx] === 1) {
                this.V[0xF] = 1;
              }
              this.display[idx] ^= 1;
            }
          }
        }
        this.drawFlag = true;
        this.pc += 2;
        break;

      case 0xE000:
        switch (NN) {
          case 0x9E: // EX9E - Skip if key VX is pressed
            if (this.key[this.V[X]] !== 0) {
              this.pc += 4;
            } else {
              this.pc += 2;
            }
            return;
          case 0xA1: // EXA1 - Skip if key VX is not pressed
            if (this.key[this.V[X]] === 0) {
              this.pc += 4;
            } else {
              this.pc += 2;
            }
            return;
          default:
            console.log('Unknown opcode: ' + opcode.toString(16));
        }
        break;

      case 0xF000:
        switch (NN) {
          case 0x07: // FX07 - Set VX = delay timer
            this.V[X] = this.delayTimer;
            break;
          case 0x0A: // FX0A - Wait for key press
            this.waitingForKey = true;
            this.waitingForKeyRegister = X;
            return;
          case 0x15: // FX15 - Set delay timer = VX
            this.delayTimer = this.V[X];
            break;
          case 0x18: // FX18 - Set sound timer = VX
            this.soundTimer = this.V[X];
            break;
          case 0x1E: // FX1E - Add VX to I
            this.I = (this.I + this.V[X]) & 0xFFFF;
            break;
          case 0x29: // FX29 - Set I = font address of VX
            this.I = FONTSET_ADDRESS + (this.V[X] * 5);
            break;
          case 0x33: // FX33 - BCD of VX at I
            const val = this.V[X];
            this.memory[this.I] = Math.floor(val / 100);
            this.memory[this.I + 1] = Math.floor((val % 100) / 10);
            this.memory[this.I + 2] = val % 10;
            break;
          case 0x55: // FX55 - Store V0-VX at I
            for (let i = 0; i <= X; i++) {
              this.memory[this.I + i] = this.V[i];
            }
            break;
          case 0x65: // FX65 - Load V0-VX from I
            for (let i = 0; i <= X; i++) {
              this.V[i] = this.memory[this.I + i];
            }
            break;
          default:
            console.log('Unknown opcode: ' + opcode.toString(16));
        }
        this.pc += 2;
        break;

      default:
        console.log('Unknown opcode: ' + opcode.toString(16));
    }
  }

  decodeInstruction(opcode) {
    const X = (opcode & 0x0F00) >> 8;
    const Y = (opcode & 0x00F0) >> 4;
    const N = opcode & 0x000F;
    const NN = opcode & 0x00FF;
    const NNN = opcode & 0x0FFF;

    const op = opcode & 0xF000;

    switch (op) {
      case 0x0000:
        if (NNN === 0x00E0) return '00E0 - CLS';
        if (NNN === 0x00EE) return '00EE - RET';
        return '0NNN - CALL BCD';
      case 0x1000: return `1NNN - JP ${NNN.toString(16).toUpperCase()}`;
      case 0x2000: return `2NNN - CALL ${NNN.toString(16).toUpperCase()}`;
      case 0x3000: return `3XNN - SE V${X.toString(16).toUpperCase()}, ${NN.toString(16).toUpperCase()}`;
      case 0x4000: return `4XNN - SNE V${X.toString(16).toUpperCase()}, ${NN.toString(16).toUpperCase()}`;
      case 0x5000: return `5XY0 - SE V${X.toString(16).toUpperCase()}, V${Y.toString(16).toUpperCase()}`;
      case 0x6000: return `6XNN - LD V${X.toString(16).toUpperCase()}, ${NN.toString(16).toUpperCase()}`;
      case 0x7000: return `7XNN - ADD V${X.toString(16).toUpperCase()}, ${NN.toString(16).toUpperCase()}`;
      case 0x8000:
        switch (N) {
          case 0x0: return `8XY0 - LD V${X.toString(16).toUpperCase()}, V${Y.toString(16).toUpperCase()}`;
          case 0x1: return `8XY1 - OR V${X.toString(16).toUpperCase()}, V${Y.toString(16).toUpperCase()}`;
          case 0x2: return `8XY2 - AND V${X.toString(16).toUpperCase()}, V${Y.toString(16).toUpperCase()}`;
          case 0x3: return `8XY3 - XOR V${X.toString(16).toUpperCase()}, V${Y.toString(16).toUpperCase()}`;
          case 0x4: return `8XY4 - ADD V${X.toString(16).toUpperCase()}, V${Y.toString(16).toUpperCase()}`;
          case 0x5: return `8XY5 - SUB V${X.toString(16).toUpperCase()}, V${Y.toString(16).toUpperCase()}`;
          case 0x6: return `8XY6 - SHR V${X.toString(16).toUpperCase()}`;
          case 0x7: return `8XY7 - SUBN V${X.toString(16).toUpperCase()}, V${Y.toString(16).toUpperCase()}`;
          case 0x8: return `8XYE - SHL V${X.toString(16).toUpperCase()}`;
          default: return opcode.toString(16).toUpperCase();
        }
      case 0x9000: return `9XY0 - SNE V${X.toString(16).toUpperCase()}, V${Y.toString(16).toUpperCase()}`;
      case 0xA000: return `ANNN - LD I, ${NNN.toString(16).toUpperCase()}`;
      case 0xB000: return `BNNN - JP V0, ${NNN.toString(16).toUpperCase()}`;
      case 0xC000: return `CXNN - RND V${X.toString(16).toUpperCase()}, ${NN.toString(16).toUpperCase()}`;
      case 0xD000: return `DXYN - DRW V${X.toString(16).toUpperCase()}, V${Y.toString(16).toUpperCase()}, ${N}`;
      case 0xE000:
        if (NN === 0x9E) return `EX9E - SKP V${X.toString(16).toUpperCase()}`;
        if (NN === 0xA1) return `EXA1 - SKNP V${X.toString(16).toUpperCase()}`;
        return opcode.toString(16).toUpperCase();
      case 0xF000:
        switch (NN) {
          case 0x07: return `FX07 - LD V${X.toString(16).toUpperCase()}, DT`;
          case 0x0A: return `FX0A - LD V${X.toString(16).toUpperCase()}, K`;
          case 0x15: return `FX15 - LD DT, V${X.toString(16).toUpperCase()}`;
          case 0x18: return `FX18 - LD ST, V${X.toString(16).toUpperCase()}`;
          case 0x1E: return `FX1E - ADD I, V${X.toString(16).toUpperCase()}`;
          case 0x29: return `FX29 - LD F, V${X.toString(16).toUpperCase()}`;
          case 0x33: return `FX33 - BCD V${X.toString(16).toUpperCase()}`;
          case 0x55: return `FX55 - LD [I], V${X.toString(16).toUpperCase()}`;
          case 0x65: return `FX65 - LD V${X.toString(16).toUpperCase()}, [I]`;
          default: return opcode.toString(16).toUpperCase();
        }
      default:
        return opcode.toString(16).toUpperCase();
    }
  }

  step() {
    if (this.running) {
      const cycles = parseInt(document.getElementById('speedSlider').value);
      for (let i = 0; i < cycles; i++) {
        this.executeCycle();
        if (this.waitingForKey) {
          break;
        }
      }
    }
  }

  executeCycle() {
    const opcode = this.fetch();
    this.execute(opcode);

    // Update timers
    if (this.delayTimer > 0) {
      this.delayTimer--;
    }
    if (this.soundTimer > 0) {
      this.soundTimer--;
      if (this.soundTimer === 0) {
        // Play sound effect (beep)
      }
    }
  }

  updateDisplay() {
    const canvas = document.getElementById('display');
    const ctx = canvas.getContext('2d');
    const scale = canvas.width / DISPLAY_WIDTH;

    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#00ff88';
    for (let y = 0; y < DISPLAY_HEIGHT; y++) {
      for (let x = 0; x < DISPLAY_WIDTH; x++) {
        if (this.display[y * DISPLAY_WIDTH + x] === 1) {
          ctx.fillRect(x * scale, y * scale, scale, scale);
        }
      }
    }
  }

  updateDebugger() {
    // Update registers
    const regContainer = document.getElementById('registers');
    regContainer.innerHTML = '';
    for (let i = 0; i < 16; i++) {
      const regDiv = document.createElement('div');
      regDiv.className = 'reg';
      regDiv.innerHTML = `<span class="reg-label">V${i.toString(16).toUpperCase()}</span> <span class="reg-value">${this.V[i].toString(16).toUpperCase().padStart(2, '0')}</span>`;
      regContainer.appendChild(regDiv);
    }

    // Update I register
    document.getElementById('iReg').textContent = '0x' + this.I.toString(16).toUpperCase().padStart(3, '0');

    // Update PC
    document.getElementById('pcReg').textContent = '0x' + this.pc.toString(16).toUpperCase().padStart(3, '0');

    // Update stack
    const stackDisplay = document.getElementById('stackDisplay');
    if (this.stack.length === 0) {
      stackDisplay.textContent = 'Empty';
    } else {
      stackDisplay.textContent = this.stack.map(addr => '0x' + addr.toString(16).toUpperCase().padStart(3, '0')).join(', ');
    }

    // Update instruction
    document.getElementById('instructionDisplay').textContent = this.decodedInstruction || '-';
  }

  reset() {
    this.memory = new Uint8Array(MEMORY_SIZE);
    this.V = new Uint8Array(16);
    this.I = 0;
    this.pc = PROGRAM_ADDRESS;
    this.stack = [];
    this.sp = 0;
    this.delayTimer = 0;
    this.soundTimer = 0;
    this.display = new Uint8Array(DISPLAY_WIDTH * DISPLAY_HEIGHT);
    this.key = new Uint8Array(16);
    this.drawFlag = false;
    this.running = false;
    this.waitingForKey = false;
    this.loadFontset();
    this.updateDisplay();
    this.updateDebugger();
    document.getElementById('runBtn').classList.add('active-btn');
    document.getElementById('pauseBtn').classList.remove('active-btn');
    document.getElementById('status').textContent = 'Reset';
  }
}

// Create emulator instance
const emulator = new Chip8();

// Demo ROM - Draws a bouncing ball
const DEMO_ROM = [
